            return runtime_error(f"a folder named {name} already exists in this location")
        try:
            os.rename(src, dst)
        except OSError as e:
            return runtime_error(os_error_message(e, io_error_for_notdir=True))
        out(f"folder {blue(name)} moved")
"""
new = """        if dst.exists():
            return runtime_error(f"a folder named {name} already exists in this location")
        # The original's directory move helper treats moving a directory to
        # itself as a successful move but leaves no directory behind.
        try:
            if src.exists() and Path(target_dir).resolve(strict=True) == src.resolve(strict=True):
                shutil.rmtree(src)
                out(f"folder {blue(name)} moved")
                return 0
        except OSError:
            pass
        try:
            os.rename(src, dst)
        except OSError as e:
            return runtime_error(os_error_message(e, io_error_for_notdir=True))
        out(f"folder {blue(name)} moved")
"""
if old not in s:
    raise SystemExit('pattern not found')
p.write_text(s.replace(old,new))
